-- Prix mensuels des matières premières (FMI « Primary Commodity Prices », via
-- FRED) : huile de palme, caoutchouc, sucre, cacao, coton, Brent, et parité
-- EUR/USD pour la conversion en FCFA (1 € = 655,957 FCFA). Sert l'onglet
-- « Matières premières » de l'analyse fondamentale (PALC, SOGC, SPHC, SICC,
-- SCRC, distributeurs pétroliers). Lecture publique, écriture par le
-- service (api/process-brvm scope 'commodities').
create table if not exists public.commodity_prices (
  serie text not null,
  date date not null,
  valeur numeric not null,
  unite text not null,
  source text not null default 'FMI via FRED',
  updated_at timestamptz not null default now(),
  primary key (serie, date)
);

alter table public.commodity_prices enable row level security;
drop policy if exists "commodity_prices_public_read" on public.commodity_prices;
create policy "commodity_prices_public_read" on public.commodity_prices
  for select to anon, authenticated using (true);
grant select on public.commodity_prices to anon, authenticated;

-- Historique mensuel depuis janvier 2015 (une valeur par mois, séries contiguës), tel que publié le 25/09/2026.
insert into public.commodity_prices (serie, date, valeur, unite, source)
select x.s, (x.d0 + make_interval(months => (t.i - 1)::int))::date, t.val, x.u, 'FMI via FRED (' || x.f || ')'
