-- Mise à jour chaque lundi à 6 h 10 UTC (le FMI publie le mois écoulé en début de mois ; FRED le reprend dans la semaine).
select cron.unschedule(jobid) from cron.job where jobname = 'tc-commodities-sync';
select cron.schedule(
  'tc-commodities-sync',
  '10 6 * * 1',
  $$select public.tc_call_api('/api/process-brvm', 'POST', '{"scope":"commodities","since":"2024-01-01"}'::jsonb)$$
);
